\newcommand{\vv}{\nu_2}

\title{Exact 2-adic Valuations of the Coefficients of $T(x)^m$:\\
the $m=5$ Law and the Failure of a Universal Formula}
\author{Aristotle}
\date{2026-07-05}

\begin{document}
\maketitle

\begin{abstract}
Let $T(x) = \prod_{k\ge 0}\bigl(1 - x^{2^k}\bigr)$ be the generating function of the
Thue--Morse sign sequence, and for an odd integer $m$ write
$T(x)^m = \sum_{n\ge 0} t_m(n)\,x^n$. We study the $2$-adic valuation $\vv(t_m(n))$.
A widely plausible conjecture predicts, for every $m\equiv 1\pmod 4$, the block-constant law
$\vv(t_m((m-1)n+j)) = (m-1)\lceil \vv(n+1)/2\rceil - \tfrac{m-1}{4}(\vv(n+1)\bmod 2)$
for $j\in\{0,\dots,m-2\}$. We prove this is false in general: it fails at $m=9$, where
$t_9(8)=2376=2^3\cdot 297$ has valuation $3$ while the formula predicts $6$. The conjecture
holds precisely for $m=5$, where it specializes to
$\vv(t_5(4q+j)) = 2\vv(q+1)+(\vv(q+1)\bmod 2)$ for $j\in\{0,1,2,3\}$. We give the self-similar
recursion defining $t_5$, establish a mod-$2$ collapse of that recursion, and prove in full
generality the ground layer of the corrected law: $t_5(n)$ is odd if and only if
$\lfloor n/4\rfloor$ is even. We locate the reason $m=5$ is exceptional in the $2$-adic content
of the binomial coefficients of $(1-x)^m$, describe the distinct $m=9$ law and the breakdown of
block-constancy at $m=13$, and pose conjectures on the general $m$-dependent law and its
automaticity.
\end{abstract}

\section{Introduction}

The \emph{Thue--Morse sequence} is the sequence of signs $\varepsilon(n) = (-1)^{s(n)}$, where
$s(n)$ is the number of $1$'s in the binary expansion of $n$. Its generating function
\[
T(x) = \sum_{n\ge 0}\varepsilon(n)\,x^n = \prod_{k\ge 0}\bigl(1-x^{2^k}\bigr) = (1-x)(1-x^2)(1-x^4)\cdots
\]
satisfies the \emph{functional equation}
\begin{equation}
T(x) = (1-x)\,T(x^2). \tag{1}
\end{equation}
For an odd exponent $m$ we write $T(x)^m = \sum_{n\ge 0} t_m(n)x^n$; the coefficients $t_m(n)$
are integer signed convolution counts. We write $\vv(a)$ for the $2$-adic valuation (the largest
$e$ with $2^e\mid a$, and $\vv(0)=\infty$). Our contributions are: (i) a refutation of a natural
universal valuation formula; (ii) identification of $m=5$ as the unique case where it holds;
(iii) a proved mod-$2$ ground layer of the corrected $m=5$ law; and (iv) a structural explanation
plus conjectures for general $m$.

\section{The self-similar recursion}

Raising (1) to the power $m$ gives
\begin{equation}
T(x)^m = (1-x)^m\,T(x^2)^m. \tag{2}
\end{equation}
Since $T(x^2)^m$ is supported on even powers and $(1-x)^m=\sum_{r=0}^m\binom{m}{r}(-1)^r x^r$ has
$m+1$ terms, extracting the coefficient of $x^n$ in (2) expresses $t_m(n)$ through values at half
scale.

\begin{definition}[coefficients of $T(x)^5$]
With $(1-x)^5 = 1 - 5x + 10x^2 - 10x^3 + 5x^4 - x^5$, equation (2) yields the doubling recursion
\begin{equation}
\begin{aligned}
t_5(2s) &= t_5(s) + 10\,t_5(s-1) + 5\,t_5(s-2),\\
t_5(2s+1) &= -\bigl(5\,t_5(s) + 10\,t_5(s-1) + t_5(s-2)\bigr),
\end{aligned}\tag{3}
\end{equation}
with $t_5(0)=1$ and $t_5(k)=0$ for $k<0$.
\end{definition}

The recursion (3) defines the same integers as the direct $5$-fold Cauchy convolution of the
Thue--Morse signs, so $t_5(n)$ is genuinely the coefficient of $x^n$ in $T(x)^5$. The first values
are $1,-5,5,15,-40,24,40,-120,135,45,-301,265,80,-400,400,176,\dots$

\section{The universal conjecture and its refutation}

\begin{conjecture}[universal block-constant law]
For every odd $m\equiv 1\pmod 4$, all $n\ge 0$, and all $j\in\{0,\dots,m-2\}$,
\begin{equation}
\vv\bigl(t_m((m-1)n+j)\bigr) = (m-1)\left\lceil\tfrac{\vv(n+1)}{2}\right\rceil
- \tfrac{m-1}{4}\bigl(\vv(n+1)\bmod 2\bigr). \tag{4}
\end{equation}
\end{conjecture}

\begin{theorem}[refutation at $m=9$]
Conjecture~1 is false. At $m=9,\,n=1,\,j=0$ the index is $8$ and $\vv(n+1)=\vv(2)=1$, so (4)
predicts $\vv(t_9(8)) = 8\lceil\tfrac12\rceil - 2(1\bmod 2) = 6$. But
$t_9(8)=2376 = 2^3\cdot 297$, so $\vv(t_9(8))=3\ne 6$.
\end{theorem}

\begin{proof}[Proof sketch]
The value $t_9(8)=2376$ is obtained by convolving the Thue--Morse sign sequence with itself nine
times and reading the coefficient of $x^8$. Since $2376=2^3\cdot 297$ with $297$ odd, $2^3\mid t_9(8)$
and $2^4\nmid t_9(8)$, hence $\vv(t_9(8))=3$ and $2^6\nmid t_9(8)$, contradicting the prediction $6$.
\end{proof}

The failure is structural. For $m=9$ the valuation is still block-constant but obeys
\begin{equation}
\vv\bigl(t_9(8n+j)\bigr) = \left\lfloor\tfrac{5\vv(n+1)+(\vv(n+1)\bmod 2)}{2}\right\rfloor,
\qquad j\in\{0,\dots,7\},\tag{5}
\end{equation}
giving $3$ at $n=1$, in agreement with the theorem. For $m=13$ block-constancy itself breaks: for
$n=2$ the twelve offsets give valuations $4,4,4,4,10,7,6,6,0,0,0,0$. Thus Conjecture~1 holds exactly
for $m=5$.

\section{The exact $m=5$ law and its proved ground layer}

\begin{theorem}[corrected $m=5$ law]
For all $q\ge 0$ and $j\in\{0,1,2,3\}$,
\begin{equation}
\vv\bigl(t_5(4q+j)\bigr) = 2\,\vv(q+1) + \bigl(\vv(q+1)\bmod 2\bigr). \tag{6}
\end{equation}
In particular $\vv(t_5(n))$ depends on $n$ only through $\lfloor n/4\rfloor$.
\end{theorem}

We prove the fibre $\vv(q+1)=0$ of (6) in full generality via a mod-$2$ collapse of (3).

\begin{lemma}[parity of the coefficients of $(1-x)^5$]
Modulo $2$, $(1-x)^5\equiv 1+x+x^4+x^5=(1+x)(1+x^4)$, since $\binom{5}{2}=\binom{5}{3}=10$ are even.
Hence both branches of (3) have identical parity structure and the overall sign in the odd branch is
irrelevant mod $2$.
\end{lemma}

\begin{theorem}[mod-2 collapse]
For all $n\ge 4$,
\begin{equation}
t_5(n)\equiv t_5\!\left(\lfloor n/2\rfloor\right) + t_5\!\left(\lfloor n/2\rfloor - 2\right)\pmod 2.\tag{7}
\end{equation}
\end{theorem}

\begin{proof}[Proof sketch]
In (3) the middle term $10\,t_5(s-1)$ is even and $5\equiv 1\pmod 2$, so the even branch gives
$t_5(2s)\equiv t_5(s)+t_5(s-2)$ and the odd branch (sign invisible mod $2$) gives
$t_5(2s+1)\equiv t_5(s)+t_5(s-2)$, both with $s=\lfloor n/2\rfloor$.
\end{proof}

\begin{theorem}[exact parity law]
For all $n\ge 0$, $\;t_5(n)\bmod 2 = 1-(\lfloor n/4\rfloor\bmod 2)$; equivalently $t_5(n)$ is odd iff
$\lfloor n/4\rfloor$ is even.
\end{theorem}

\begin{proof}[Proof sketch]
Strong induction using (7). The base window $0\le n<8$ is checked directly ($t_5(0),\dots,t_5(3)$ odd,
$t_5(4),\dots,t_5(7)$ even). For $n\ge 8$, (7) reduces the parity of $t_5(n)$ to a combination of
values at $\lfloor n/2\rfloor,\lfloor n/2\rfloor-2<n$; substituting the induction hypothesis and a
finite case analysis on $n\bmod 8$ yields $1-(\lfloor n/4\rfloor\bmod 2)$.
\end{proof}

\begin{corollary}[ground layer]
For $q$ even ($\vv(q+1)=0$) and all $j\in\{0,1,2,3\}$, $\vv(t_5(4q+j))=0$, which is (6) restricted to
$\vv(q+1)=0$. Theorem~7 is an exact parity statement, hence non-vacuous for every $n$, and verifies (6)
on the infinite family of even blocks.
\end{corollary}

\section{Why $m=5$ is exceptional}

By Kummer's theorem $\vv\binom{m}{r}$ counts the carries in adding $r$ and $m-r$ in base $2$;
equivalently, by Lucas' theorem, $\binom{m}{r}$ is odd iff the binary digits of $r$ are dominated by
those of $m$. For $m=5=(101)_2$ the odd binomial coefficients occur at $r\in\{0,1,4,5\}$, splitting
evenly between the even and odd branches of (3) so they coincide mod $2$ (Lemma~5), forcing
$\vv(t_5(\cdot))$ to depend only on $\lfloor n/4\rfloor$. For $m=9=(1001)_2$ this alignment yields a
different slope (law (5)); for $m=13=(1101)_2$ enough dyadic scales are active that the valuation
separates across offsets, breaking block-constancy. The valuation's growth rate is set not by the
naive $m-1$ but by the Kummer/Lucas carry pattern of $m$.

\section{Applications}

Coefficients of $T(x)^m$ are signed counts from repeated binary convolutions, structurally identical
to the accumulation of low-precision products in fixed-point and integer arithmetic pipelines. The
valuation $\vv(t_m(n))$ counts the guaranteed-zero low bits of a coefficient --- the headroom before
rounding noise appears. An exact valuation law is thus an exact statement about the noise floor of a
cascade of binary products, predictable in closed form when the binomial carries align.

\section{Future work}

(i) A conjectural piecewise-linear law $\Phi_m$ of $\vv(n+1)$ with slope governed by the $2$-adic
content of the binomial coefficients of $(1-x)^m$, pinned by the $m=5$ and $m=9$ laws. (ii)
Block-constancy conjecturally holds exactly when $(1-x)^m$ has a single active dyadic scale, with the
number of $j$-classes otherwise equal to the binary weight of $m$. (iii) The odd-part sequence of
$T(x)^5$ is conjecturally $2$-automatic, generated by a transducer whose selector is the Thue--Morse
word itself. (iv) Higher layers of (6) require tracking odd parts modulo higher powers of $2$.

\section{Conclusion}

A natural universal $2$-adic valuation formula for the coefficients of $T(x)^m$ is false, failing first
at $m=9$ where $t_9(8)=2376$ has valuation $3$ rather than $6$. It holds precisely for $m=5$, whose
exceptional status is explained by the parity of the binomial coefficients of $(1-x)^5$. On the mod-$2$
layer we prove the corrected $m=5$ law in full generality: $t_5(n)$ is odd exactly when
$\lfloor n/4\rfloor$ is even.

