from typing import List

def thue_morse_sign(n: int) -> int:
    """Thue-Morse sign epsilon(n) = (-1)^popcount(n)."""
    return -1 if (bin(n).count("1") & 1) else 1

def tmpow(m: int, length: int) -> List[int]:
    """Coefficients t_m(0..length-1) of T(x)^m by m-fold convolution of the
    Thue-Morse signs (the definitional coefficient sequence)."""
    coeff: List[int] = [thue_morse_sign(n) for n in range(length)]
    res: List[int] = [1] + [0] * (length - 1)
    for _ in range(m):
        new: List[int] = [0] * length
        for i in range(length):
            if res[i]:
                for j in range(length - i):
                    new[i + j] += res[i] * coeff[j]
        res = new
    return res

if __name__ == "__main__":
    for m in (1, 3, 5, 7, 9):
        print(f"T(x)^{m} coefficients:", tmpow(m, 12))

from typing import List

def v2(a: int) -> int:
    """2-adic valuation of a (largest e with 2^e | a); 10**9 for a == 0."""
    if a == 0:
        return 10 ** 9
    a, e = abs(a), 0
    while a % 2 == 0:
        a //= 2
        e += 1
    return e

def t5_recursion(length: int) -> List[int]:
    """t_5 via the doubling recursion of T(x)^5 = (1-x)^5 T(x^2)^5."""
    t: List[int] = [0] * length
    if length:
        t[0] = 1
    g = lambda k: t[k] if 0 <= k < length else 0
    for n in range(1, length):
        s = n // 2
        t[n] = (g(s) + 10 * g(s - 1) + 5 * g(s - 2)) if n % 2 == 0 else                -(5 * g(s) + 10 * g(s - 1) + g(s - 2))
    return t

def m5_law(q: int) -> int:
    """Corrected m=5 law: nu_2(t_5(4q+j)) = 2 v2(q+1) + (v2(q+1) mod 2)."""
    v = v2(q + 1)
    return 2 * v + (v % 2)

if __name__ == "__main__":
    t5 = t5_recursion(200)
    for q in range(16):
        actual = [v2(t5[4 * q + j]) for j in range(4)]
        print(f"q={q:2d}  predicted={m5_law(q)}  actual across j=0..3={actual}")

