def tmpow(m: int, length: int) -> List[int]:
    coeff = [thue_morse_sign(n) for n in range(length)]
    res = [1] + [0] * (length - 1)
    for _ in range(m):
        new = [0] * length
        for i in range(length):
            if res[i]:
                for j in range(length - i):
                    new[i + j] += res[i] * coeff[j]
        res = new
