def v2(a: int) -> int:
    if a == 0:
        return 10 ** 9
    a, e = abs(a), 0
    while a % 2 == 0:
        a //= 2; e += 1
    return e

def universal_prediction(m: int, n: int) -> int:
    v = v2(n + 1)
    return (m - 1) * ((v + 1) // 2) - ((m - 1) // 4) * (v % 2)

def smallest_witness() -> Tuple[int, int, int, int]:
    """Search m in {5,9,13,17,21,25}, n<60, for the first failure of the
    universal formula; returns (m, index, actual nu_2, predicted nu_2)."""
    for m in (5, 9, 13, 17, 21, 25):
        t = tmpow(m, (m - 1) * 60 + m)
        for n in range(60):
            for j in range(m - 1):
                idx = (m - 1) * n + j
                if v2(t[idx]) != universal_prediction(m, n):
                    return (m, idx, v2(t[idx]), universal_prediction(m, n))
    return (-1, -1, -1, -1)

if __name__ == "__main__":
    m, idx, actual, pred = smallest_witness()
    t = tmpow(m, idx + 1)
    print(f"first failure: m={m}, index={idx}, t_m(idx)={t[idx]}")
    print(f"  actual nu_2 = {actual}, universal formula predicts {pred}")

